import { Kafka, EachMessagePayload } from 'kafkajs';
import { Pool } from 'pg';

const kafka = new Kafka({ clientId: 'order-events-consumer', brokers: [process.env.KAFKA_BROKERS!] });
const consumer = kafka.consumer({ groupId: 'order-events-group' });
const pg = new Pool({ connectionString: process.env.DATABASE_URL });

interface OrderEvent {
  eventId: string;
  orderId: string;
  amount: number;
  status: string;
}

// processed_events table (durable ground truth):
//   CREATE TABLE processed_events (
//     event_id    TEXT PRIMARY KEY,
//     processed_at TIMESTAMPTZ NOT NULL DEFAULT now()
//   );
//   -- PRIMARY KEY already enforces UNIQUE(event_id)

async function processOrder(event: OrderEvent): Promise<void> {
  // ... real business logic: update order status, emit downstream events, etc.
  console.log(`processed order ${event.orderId} with status ${event.status}`);
}

async function handleMessage({ topic, partition, message }: EachMessagePayload): Promise<void> {
  if (!message.value) return;

  const event = JSON.parse(message.value.toString()) as OrderEvent;
  const eventId = event.eventId;

  try {
    // Every single message -- original AND every redelivered duplicate --
    // pays a full Postgres round-trip here before we even know if it's new.
    await pg.query(
      `INSERT INTO processed_events (event_id, processed_at) VALUES ($1, now())`,
      [eventId],
    );
  } catch (err: any) {
    if (err.code === '23505') {
      // Unique violation -> we've already processed this event id, skip it.
      console.log(`duplicate event ${eventId}, skipping`);
      return;
    }
    throw err;
  }

  // Only reached on a fresh event id.
  await processOrder(event);
}

async function run(): Promise<void> {
  await consumer.connect();
  await consumer.subscribe({ topic: 'order-events', fromBeginning: false });
  await consumer.run({
    eachMessage: handleMessage,
  });
}

run().catch((err) => {
  console.error('consumer crashed', err);
  process.exit(1);
});
